@Service
public class PricingService {
    private final TaxRateRepository taxRates;

    public PricingService(TaxRateRepository taxRates) {
        this.taxRates = taxRates;
    }

    @Transactional(readOnly = true)
    public Money basePrice(long productId) { ... }

    @Transactional(readOnly = true)
    public Money priceWithTax(long productId, String region) {   // bỏ final
        Money base = basePrice(productId);                        // self-invocation: chạy trong transaction của method này
        return base.plus(base.times(taxRates.rateFor(region)));
    }
}
